// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Library: none — native interpolate/spring for sequential UI reveals and wipe masks.

const { fontFamily: oswaldFamily } = loadOswald();



export type HighlighterSwipeProps = Record<string, any>;

const HighlighterSwipe: React.FC<HighlighterSwipeProps> = ({
  backgroundColor = "#160C28",
  transparentBackground = false,
  durationInSeconds = 5,
  attnText = "ATTN:",
  attnChipColor = "#C6A4FF",
  attnTextColor = "#160C28",
  modalities = ["PILATES", "YOGA", "BARRE"],
  highlighterColor = "#A865FF",
  modalityTextColor = "#FFFFFF",
  footerTextPart1 = "STUDIO",
  footerTextPart2 = "OWNERS!",
  footerColor1 = "#FFFFFF",
  footerColor2 = "#A865FF",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080; 

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const attnStart = 5;
  const modInitialDelay = 15;
  const modStagger = 8; // Fast sequence
  const wipeDuration = 5; // Fast wipe per modality
  const footerStart = attnStart + modInitialDelay + (modalities.length * modStagger) + 10;

  // ATTN Entrance
  const attnScale = spring({
    fps,
    frame: frame - attnStart,
    config: { damping: 12, mass: 0.8 },
  });
  const attnOpacity = interpolate(frame, [attnStart, attnStart + 4], [0, 1], { extrapolateRight: "clamp" });

  // Footer Entrance
  const footerScale = spring({
    fps,
    frame: frame - footerStart,
    config: { damping: 12, mass: 0.8 },
  });
  const footerOpacity = interpolate(frame, [footerStart, footerStart + 4], [0, 1], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: oswaldFamily,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        paddingTop: height * 0.15, // Places the block in the top ~40% as requested
      }}
    >
      {/* ATTN Chip */}
      <div
        style={{
          backgroundColor: attnChipColor,
          padding: `${12 * s}px ${40 * s}px`,
          borderRadius: 32 * s,
          marginBottom: 40 * s,
          opacity: attnOpacity,
          transform: `scale(${attnScale})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <span
          style={{
            color: attnTextColor,
            fontSize: 110 * s,
            fontWeight: 700,
            fontStyle: "italic",
            lineHeight: 1,
            textTransform: "uppercase",
            letterSpacing: "-0.01em",
            transform: `translateY(-2%)`, // optical centering for uppercase
          }}
        >
          {attnText}
        </span>
      </div>

      {/* Modalities Stack */}
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
        {modalities.map((text, i) => {
          const startFrame = attnStart + modInitialDelay + i * modStagger;
          
          // Left-to-right wipe progress (0 to 100%)
          const wipeProgress = interpolate(frame, [startFrame, startFrame + wipeDuration], [0, 100], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Layout stability: Keep mounted, but fully transparent before entrance
          const isVisible = frame >= startFrame;

          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                marginBottom: 16 * s,
                opacity: isVisible ? 1 : 0,
                // Inset clip path cuts from the right side. inset(0 100% 0 0) is fully hidden, inset(0 0% 0 0) is fully revealed.
                clipPath: `inset(0 ${100 - wipeProgress}% 0 0)`,
                willChange: "clip-path",
                transition: "none",
              }}
            >
              {/* Marker Tip (Chisel end) */}
              <div
                style={{
                  width: 20 * s,
                  height: 64 * s,
                  backgroundColor: highlighterColor,
                  borderTopLeftRadius: 6 * s,
                  borderBottomLeftRadius: 6 * s,
                  marginRight: 6 * s,
                }}
              />
              {/* Marker Body with Text */}
              <div
                style={{
                  backgroundColor: highlighterColor,
                  padding: `${8 * s}px ${36 * s}px`,
                  borderRadius: 16 * s,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <span
                  style={{
                    color: modalityTextColor,
                    fontSize: 140 * s,
                    fontWeight: 700,
                    fontStyle: "italic",
                    lineHeight: 1,
                    textTransform: "uppercase",
                    transform: `translateY(-2%)`,
                  }}
                >
                  {text}
                </span>
              </div>
            </div>
          );
        })}
      </div>

      {/* Footer Snaps In */}
      <div
        style={{
          marginTop: 40 * s,
          opacity: footerOpacity,
          transform: `scale(${footerScale})`,
          display: "flex",
          gap: 16 * s,
        }}
      >
        <span
          style={{
            color: footerColor1,
            fontSize: 130 * s,
            fontWeight: 700,
            fontStyle: "italic",
            lineHeight: 1,
            textTransform: "uppercase",
            letterSpacing: "-0.01em",
          }}
        >
          {footerTextPart1}
        </span>
        <span
          style={{
            color: footerColor2,
            fontSize: 130 * s,
            fontWeight: 700,
            fontStyle: "italic",
            lineHeight: 1,
            textTransform: "uppercase",
            letterSpacing: "-0.01em",
          }}
        >
          {footerTextPart2}
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default HighlighterSwipe;